@Override
public String toString() {
    final StringBuilder builder = new StringBuilder("Deprecated");
    if (forRemoval) {
        builder.append(" for removal");
    }
    if (!since.isEmpty()) {
        builder.append(" since ");
        builder.append(since);
    }
    if (!description.isEmpty()) {
        builder.append(": ");
        builder.append(description);
    }
    return builder.toString();
}
